from pathlib import Path


def block(src,start,end,new):
    i=src.index(start); j=src.index(end,i)
    return src[:i]+new+'\n\n'+src[j:]

p=Path('app.js')
s=p.read_text()

s=s.replace("const capacity=()=>1+(Math.max(1,Number(S?.player?.quarters_level||1))-1)*2;","const capacity=()=>Number(S?.quartersCapacity||3+(Math.max(1,Number(S?.player?.quarters_level||1))-1)*2);",1)
needle="const saleInfo=id=>{const r=recipeForOutput(id);if(r)return {item:id,unitGold:Number(r.sale_gold||0),unitSeconds:Math.max(1,Math.ceil(Number(r.craft_seconds||1)/1.2)),kind:'finished'};const d=rawSaleDef(id);return d?{item:id,unitGold:Number(d.sale_gold||0),unitSeconds:Number(d.sell_seconds||1),kind:'raw'}:null};"
add=needle+"\nconst recruitBatch=()=>Math.max(4,Number(S?.player?.tavern_level||1)+3);\nconst dropRarity=c=>{c=Number(c||0);return c>=.4?'흔함':c>=.2?'일반':c>=.05?'고급':c>=.005?'희귀':c>=.001?'매우 희귀':'극희귀'};\nconst dropRate=c=>{const p=Number(c||0)*100;return p>=1?`${p.toFixed(p%1?1:0)}%`:p>=.1?`${p.toFixed(2)}%`:`${p.toFixed(3)}%`};"
if needle not in s: raise SystemExit('helper target missing')
s=s.replace(needle,add,1)

s=block(s,'function hq(){','function dormModal(){',r'''function hq(){const active=(S.expeditions||[]).filter(e=>e.active),pending=totalPending(),cap=capacity(),used=inventoryUsed(),craftJobs=activeCraftJobs(),sellJobs=activeSellJobs();return `
<section class="facility-stack">
  <button class="facility-row dorm" data-action="dorm"><img src="assets/icon-dorm.svg" alt=""><span class="facility-copy"><b>숙소</b><small>${S.monsters.length}/${cap} 몬스터</small></span><span class="facility-side"><em>Lv.${S.player.quarters_level}</em><i>›</i></span></button>
  <button class="facility-row recruit" data-action="candidates"><img src="assets/icon-recruit.svg" alt=""><span class="facility-copy"><b>영입소</b><small>3시간마다 ${recruitBatch()}명 · 현재 ${(S.candidates||[]).length}명</small></span><span class="facility-side"><em>Lv.${S.player.tavern_level}</em><i>›</i></span></button>
  <button class="facility-row workshop" data-action="workshop"><img src="assets/icon-workshop.svg" alt=""><span class="facility-copy"><b>제작소</b><small>작업 ${craftJobs.length}/${S.craftCapacity||6} · 대기열 ${Math.max(0,Number(S.craftCapacity||6)-1)}</small></span><span class="facility-side"><em>Lv.${S.player.workshop_level||1}</em><i>›</i></span></button>
  <button class="facility-row shop" data-action="shop"><img src="assets/icon-shop.svg" alt=""><span class="facility-copy"><b>상점</b><small>판매 ${sellJobs.length}/${S.shopCapacity||6} · 대기열 ${Math.max(0,Number(S.shopCapacity||6)-1)}</small></span><span class="facility-side"><em>Lv.${S.player.shop_level||1}</em><i>›</i></span></button>
  <button class="facility-row storage" data-go="loot"><img src="assets/icon-storage.svg" alt=""><span class="facility-copy"><b>전리품 창고</b><small>${pending}개 회수 대기 · ${used}/${S.storageCapacity||40}</small></span><span class="facility-side"><em>Lv.${S.player.storage_level||1}</em><i>›</i></span></button>
</section>
${active.length?`<section class="home-live"><header><b>진행 중인 작전</b><small>${active.length}건</small></header>${active.slice(0,3).map(e=>{const site=S.sites.find(x=>x.id===e.site_id),p=partyOf(e);return `<button data-action="watch" data-id="${e.id}"><span class="live-pin"></span><span><b>${esc(site?.name||'작전')}</b><small>${esc(partyLabel(e))} · ${p.length}인 · 승리 ${fmt(e.kills)} · 화물 ${lootCount(e)}</small></span><i>관전</i></button>`}).join('')}</section>`:''}`}
''')

s=block(s,'function hunt(){','function loot(){',r'''function hunt(){const active=(S.expeditions||[]).filter(e=>e.active);return `
<div class="compact-head"><div><b>박멸 작전</b><small>${active.length}개 파티 출동 중 · 몬스터별 자유 파견</small></div></div>
<section class="mission-list compact-missions">${S.sites.map(site=>{const ex=activeAt(site.id),unlocked=!!site.unlocked,pending=ex.reduce((a,e)=>a+lootCount(e),0),wins=Number(site.progress?.normal_wins||0),bossReady=!!site.progress?.boss_ready,bossCleared=!!site.progress?.boss_cleared,pct=bossCleared?100:Math.min(100,wins/500*100),party=ex[0]?partyOf(ex[0]):[],drops=(site.loot||[]).length;return `<article class="mission-card compact-mission ${unlocked?'':'locked'}" data-action="mission" data-id="${site.id}" data-site="${site.id}"><div class="mission-art"></div><div class="mission-wash"></div><div class="mission-file"><header><div><div class="mission-code">${siteCode(site.id)}</div><div class="mission-title">${esc(site.name)}${bossReady?'<span class="boss-flag">BOSS</span>':bossCleared?'<span class="boss-flag cleared">CLEAR</span>':''}</div></div><span class="risk">권장 ${fmt(site.recommended_power)}</span></header><div class="mission-middle"><div class="squad">${party.length?party.slice(0,4).map(mm=>`<span class="party-avatar">${charSvg(monsterAsset(mm.family),'party-sprite')}</span>`).join(''):'<span class="empty-slot">+</span>'}</div></div><footer class="mission-foot"><div><div class="op-state">${ex.length?`${esc(ex[0]?.phase||'탐색')} · ${party.length}인 · 화물 ${pending}`:(unlocked?(bossReady?'보스 출현':bossCleared?`보스 격파 · 드롭 ${drops}종`:`파티 배치 가능 · 드롭 ${drops}종`):'이전 보스 처치 필요')}</div><div class="stage-progress"><span><i style="width:${pct}%"></i></span><small>${bossCleared?'완료':bossReady?'500/500':`${Math.min(500,wins)}/500`}</small></div></div><div class="mission-cta"><b>${unlocked?(ex.length?'현장':'상세'):'잠김'}</b></div></footer></div></article>`}).join('')}</section>`}
''')

s=block(s,'function candidateModal(){','function employeeModal(',r'''function candidateModal(){const lv=Number(S.player.tavern_level||1),batch=recruitBatch();modal(`<div class="sheet-head"><div><div class="section-kicker">RECRUITING</div><h2>영입소</h2><p>3시간마다 새 지원자 배치가 도착합니다.</p></div><button class="close-btn" data-action="close">×</button></div><div class="facility-upgrade"><span><small>영입소 Lv.${lv}</small><b>다음 배치 ${batch}명 · 레벨당 +1명 · A/S급 확률 상승</b></span><button class="soft-btn" data-action="upgrade" data-id="tavern">확장 ${fmt(nextTavernCost())}G</button></div><div class="candidate-list">${(S.candidates||[]).length?S.candidates.map(c=>`<div class="candidate-card"><div class="candidate-avatar">${charSvg(monsterAsset(c.family),'candidate-sprite')}</div><div><b><span class="candidate-grade ${esc(c.growth_grade||'C')}">${esc(c.growth_grade||'C')}</span>${esc(c.name)} · ${fam(c.family)}</b><small>재능 ${c.talent} · ${esc(c.personality||'침착')} · ${esc(c.trait||'무특성')}</small><span class="candidate-fit">HP ${fmt(c.hp_base)} · 공격 ${fmt(c.atk_base)} · 방어 ${fmt(c.def_base)}</span></div><div class="actions"><button class="primary-btn" data-action="hire" data-id="${c.id}">${fmt(c.hire_cost||0)}G 채용</button><button class="soft-btn" data-action="reject" data-id="${c.id}">거절</button></div></div>`).join(''):`<div class="empty-state">현재 대기 중인 지원자가 없습니다.<br>다음 배치까지 ${candidateText()}</div>`}</div>`,'recruit-sheet') }
''')

# Remove obsolete wording from monster detail.
s=s.replace("'박멸 작전실에서 현장에 배치할 수 있습니다.'","'박멸 화면에서 원하는 던전에 배치할 수 있습니다.'")

s=block(s,'function missionModal(siteId,keep=false){','function battleUi(',r'''function missionModal(siteId,keep=false){const site=S.sites.find(x=>x.id===siteId);if(!site)return;if(!site.unlocked){toast('이전 지역 보스를 먼저 처치해야 합니다.');return}if(!keep||partySite!==siteId){partySite=siteId;partyPick=[]}const ex=activeAt(site.id),progress=site.progress||{};partyPick=partyPick.filter(id=>!activeOf(id));const selected=S.monsters.filter(m=>partyPick.includes(m.id)),sumPower=selected.reduce((a,m)=>a+power(m),0),drops=site.loot||[];const dropRows=drops.map(l=>{const d=itemDef(l.id),eq=d?.kind==='equipment',grade=dropRarity(l.chance),qty=Number(l.min||1)===Number(l.max||1)?`${fmt(l.min||1)}개`:`${fmt(l.min||1)}~${fmt(l.max||1)}개`;return `<div class="drop-row ${eq?'equipment':''}"><span class="drop-icon">${itemSvg(itemAsset(l.id))}</span><span class="drop-name"><b>${esc(l.id)}</b><small>${eq?`장비 · ${esc(d?.rarity||'일반')}`:'제작 재료'} · ${qty}</small></span><span class="drop-rarity ${grade.replace(' ','-')}">${grade}</span><strong>${dropRate(l.chance)}</strong></div>`}).join('');modal(`<div class="sheet-head"><div><div class="section-kicker">${siteCode(site.id)}</div><h2>${esc(site.name)}${progress.boss_ready?'<span class="boss-flag"> BOSS</span>':''}</h2><p>권장 전투력 ${fmt(site.recommended_power)} · 승리 ${fmt(Math.min(500,progress.normal_wins||0))}/500</p></div><button class="close-btn" data-action="close">×</button></div><section class="drop-panel"><header><div><b>획득 가능 아이템</b><small>전투 승리 1회 기준 기본 드롭률</small></div><em>${drops.length}종</em></header><div class="drop-list">${dropRows||'<div class="shop-empty">확인된 전리품이 없습니다.</div>'}</div><p>※ 약탈광·수집광·보스 보정 전 기본 확률입니다. 장비는 매우 낮은 확률로 드롭됩니다.</p></section>${ex.length?`<div class="brief-list">${ex.map(e=>{const party=partyOf(e);return `<div class="brief-item mission-live-row"><span class="mini-avatar">${party[0]?charSvg(monsterAsset(party[0].family)):''}</span><div><b>${party.length}인 박멸조 · ${esc(partyLabel(e))}</b><small>${esc(e.phase||'탐색')} · 승리 ${fmt(e.kills)} · 화물 ${lootCount(e)}개</small><div class="party-avatars">${party.map(mm=>`<span class="party-avatar">${charSvg(monsterAsset(mm.family),'party-sprite')}</span>`).join('')}</div><div class="battle-actions"><button class="primary-btn" data-action="watch" data-id="${e.id}">관전</button><button class="danger-btn" data-action="recall" data-id="${e.id}">복귀</button></div></div></div>`}).join('')}</div>`:''}<div class="party-select-head"><b>파티 편성</b><small>최대 4마리 · 경험치 ${selected.length?`1/${selected.length}`:'-'}</small></div><div class="party-select-list">${S.monsters.map(m=>{const busy=!!activeOf(m.id),sel=partyPick.includes(m.id);return `<button class="party-select-row ${sel?'selected':''} ${busy?'busy':''}" data-action="toggle-party" data-id="${m.id}" data-site="${site.id}" ${busy?'disabled':''}><span>${charSvg(monsterAsset(m.family))}</span><span><b>${esc(m.name)} · Lv.${m.level} · ${esc(m.growth_grade||'C')}</b><small>${fam(m.family)} · 전투력 ${fmt(power(m))}${busy?' · 다른 작전 참가 중':''}</small></span><em>${sel?'선택':busy?'출동중':'+'}</em></button>`}).join('')}</div><div class="party-launch"><div class="party-summary"><span>${selected.length}/4 선택</span><span>합산 전투력 ${fmt(sumPower)}</span><span>${progress.boss_ready?'보스전 대기':'일반 탐사'}</span></div><button class="primary-btn" data-action="deploy-party" data-site="${site.id}" ${!selected.length?'disabled':''}>${progress.boss_ready?'보스 박멸조 출정':'박멸조 출정'}</button></div>`,'mission-party-sheet') }
''')

s=block(s,'function briefModal(){','function syncWatchPanel(){',r'''function briefModal(){const active=(S.expeditions||[]).filter(e=>e.active),craft=activeCraftJobs().length,sell=activeSellJobs().length;modal(`<div class="sheet-head"><div><div class="section-kicker">CONTROL ROOM BRIEF</div><h2>상황실 브리핑</h2><p>현재 회사 운영 핵심 흐름입니다.</p></div><button class="close-btn" data-action="close">×</button></div><div class="brief-list"><div class="brief-item"><i></i><div><b>전투 골드 0G</b><small>전리품을 제작소에서 가공하고 상점에서 판매해야 골드를 얻습니다.</small></div></div><div class="brief-item"><i></i><div><b>출동 파티 ${active.length} · 제작 작업 ${craft}/${S.craftCapacity||6}</b><small>상점 작업 ${sell}/${S.shopCapacity||6} · 각 시설은 순차 대기열로 처리합니다.</small></div></div><div class="brief-item"><i></i><div><b>다음 지원자 ${candidateText()}</b><small>영입소 Lv.${S.player.tavern_level||1} · 3시간마다 ${recruitBatch()}명 도착</small></div></div><div class="brief-item"><i></i><div><b>회수 대기 화물 ${totalPending()}개</b><small>창고 ${inventoryUsed()}/${S.storageCapacity||40}</small></div></div></div>`)}
''')

