css=Path('economy-v011.css');c=css.read_text();c+='''\n\n/* v0.11.5 — facility baseline + dungeon drop intelligence */\n.drop-panel{margin:7px 0 9px;padding:7px;border:1px solid #414b43;background:#151a16}.drop-panel>header{display:flex;align-items:end;justify-content:space-between;gap:8px;margin-bottom:5px}.drop-panel>header b{display:block;font-size:11px}.drop-panel>header small{display:block;margin-top:2px;font-size:7px;color:#879189}.drop-panel>header em{font-style:normal;font-size:8px;color:#d5a866}.drop-list{display:grid;gap:3px}.drop-row{height:42px;display:grid;grid-template-columns:36px minmax(0,1fr) auto 50px;align-items:center;gap:6px;padding:3px 6px;border:1px solid #343e36;background:#111512}.drop-row.equipment{border-color:#5a4936;background:#19150f}.drop-icon{width:34px;height:34px;display:grid;place-items:center}.drop-icon .pixel-item{width:30px;height:30px}.drop-name{min-width:0}.drop-name b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:9px;color:#e5e9e5}.drop-name small{display:block;margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:7px;color:#89938c}.drop-rarity{padding:2px 4px;border:1px solid #4c564f;background:#222923;color:#adb6ae;font-size:7px;white-space:nowrap}.drop-rarity.희귀{border-color:#6c6548;color:#dfca77}.drop-rarity.매우-희귀{border-color:#66527d;color:#d2a9ed}.drop-rarity.극희귀{border-color:#7b4d4d;background:#281718;color:#f3a0a0}.drop-row>strong{text-align:right;font-size:10px;color:#e1b16b;font-variant-numeric:tabular-nums}.drop-panel>p{margin:6px 1px 0;font-size:7px;line-height:1.45;color:#7f8981}.compact-head>div>small{display:block;margin-top:2px}.mission-party-sheet .drop-panel{margin-top:2px}@media(max-width:380px){.drop-row{grid-template-columns:32px minmax(0,1fr) auto 44px;gap:4px;padding:3px 4px}.drop-icon{width:30px;height:30px}.drop-icon .pixel-item{width:27px;height:27px}.drop-name small{font-size:6px}}\n''';css.write_text(c)

